svg.script:
//
    (function() {
      'use strict';

      // Dados dos Estágios no Método STE
      var STE_DATA = {
        s: {
          badge: 'PASSO 1 · SINDRÔMICO',
          badgeColor: 'var(--fm1p1-indigo, #6366f1)',
          badgeBg: 'var(--fm1p1-indigo-bg, rgba(99,102,241,0.2))',
          title: 'Reconhecer a Síndrome da Cabeça Caída',
          desc: 'Incapacidade focal de manter a sustentação cefálica por fraqueza dos extensores.',
          b1_t: 'Pergunta-Chave do Estágio:',
          b1_d: '"Qual é a manifestação funcional motora predominante?"',
          b2_t: 'Achado de Exame Físico / Âncora:',
          b2_d: 'Flexão cervical passiva sem resistência motor-extensora.',
          b2_d2: 'Paciente necessita de apoio manual constante do queixo.',
          b3_t: 'Regra de Ouro da Estação FM1:',
          b3_d: 'Não rotular doenças sem antes delimitar o compartimento axial.',
          alertTag: 'POSTURA RACIONAL STE',
          alertT1: 'Topografar primeiro guia exames direcionados.',
          alertT2: 'Evita solicitação aleatória de TC/RM de crânio e exames desnecessários.',
          alertStyle: 'green'
        },
        t: {
          badge: 'PASSO 2 · TOPOGRÁFICO',
          badgeColor: 'var(--fm1p1-amber, #f59e0b)',
          badgeBg: 'var(--fm1p1-amber-bg, rgba(245,158,11,0.2))',
          title: 'Mapear a Topografia Neuromuscular',
          desc: 'Localizar o nível lesionado: Músculo vs Placa Motora vs Raiz C2-C4 vs Corno Anterior.',
          b1_t: 'Pergunta-Chave do Estágio:',
          b1_d: '"Onde está a lesão na via motora que causa a fraqueza?"',
          b2_t: 'Subcompartimentos em Disputa:',
          b2_d: 'A. Músculo (Miopatia Axial / Polimiosite focal)',
          b2_d2: 'B. Junção Neuromuscular (Miastenia Gravis) | C. Raiz C2-C4 / NMN',
          b3_t: 'Decisão Estratégica:',
          b3_d: 'Exame clínico + ENMG de segmento cervical definem a conduta.',
          alertTag: 'ANCORAGEM ANATÔMICA CRÍTICA',
          alertT1: 'Topografia precisa reduz diagnósticos diferenciais de 50 para 3.',
          alertT2: 'Evita rotular ELA ou Miastenia precocemente sem prova de nível.',
          alertStyle: 'amber'
        },
        e: {
          badge: 'PASSO 3 · ETIOLÓGICO (SEMENTE)',
          badgeColor: 'var(--fm1p1-teal, #14b8a6)',
          badgeBg: 'var(--fm1p1-teal-bg, rgba(20,184,166,0.2))',
          title: 'Semente Etiológica (Investigação Nosológica)',
          desc: 'A etiologia é a consequência do funil, não o ponto de partida.',
          b1_t: 'Pergunta-Chave do Estágio:',
          b1_d: '"Qual a etiologia específica para a topografia confirmada?"',
          b2_t: 'Exemplos Etiológicos Específicos:',
          b2_d: 'Se JNM → Miastenia Gravis / Síndrome Miastênica',
          b2_d2: 'Se Músculo → Miopatia nemalínica / Miopatia axial isolada',
          b3_t: 'Status da Semente:',
          b3_d: 'Aguardando confirmação topográfica para desabrochar a conduta.',
          alertTag: 'ETAPA EM SEMENTE (AGUARDANDO T)',
          alertT1: 'A etiologia só acende após o afunilamento topográfico.',
          alertT2: 'Garante o diagnóstico etiológico definitivo com segurança.',
          alertStyle: 'green'
        }
      };

      var ERR_DATA = {
        badge: 'ERRO CRÍTICO · ATALHO PRECOCE',
        badgeColor: 'var(--fm1p1-red, #f43f5e)',
        badgeBg: 'var(--fm1p1-red-bg, rgba(244,63,94,0.2))',
        title: 'Chutar Etiologia Rara na Primeira Frase',
        desc: 'Tentar adivinhar a doença (ex: ELA, Miastenia) direto da queixa sem topografar.',
        b1_t: 'Vício Frequente na Prova / Ambulatório:',
        b1_d: 'Pedir RM de crânio de rotina para queixa estritamente cervical/axial.',
        b2_t: 'Consequência Diagnóstica:',
        b2_d: 'Desperdício de tempo, exames de imagem normais (encéfalo sem lesão)',
        b2_d2: 'e ansiedade desnecessária ao paciente por falta de método.',
        b3_t: 'Como Corrigir:',
        b3_d: 'Recuar ao Estágio S (Sindrômico) e obrigatoriamente passar pelo T (Topográfico).',
        alertTag: 'ALERTA DE CONDUTA INADEQUADA',
        alertT1: 'NUNCA pule a topografia em exames práticos ou simulados.',
        alertT2: 'A banca avalia o MÉTODO de raciocínio, não o chute de doenças raras.',
        alertStyle: 'red'
      };

      // Estado Atual
      var state = {
        mode: 'ste', // 'ste' ou 'err'
        stage: 's'   // 's', 't', 'e'
      };

      // Elementos do DOM
      var stageS = document.getElementById('fm1p1-stage-s');
      var stageT = document.getElementById('fm1p1-stage-t');
      var stageE = document.getElementById('fm1p1-stage-e');
      var hsNeck = document.getElementById('fm1p1-hs-neck');

      var tabSte = document.getElementById('fm1p1-tab-ste');
      var tabErr = document.getElementById('fm1p1-tab-err');

      var badgeBg = document.getElementById('fm1p1-pnl-badge-bg');
      var badgeTxt = document.getElementById('fm1p1-pnl-badge-txt');
      var mainTitle = document.getElementById('fm1p1-pnl-main-title');
      var mainDesc = document.getElementById('fm1p1-pnl-main-desc');

      var blk1Dot = document.getElementById('fm1p1-blk1-dot');
      var blk1T = document.getElementById('fm1p1-blk1-t');
      var blk1D = document.getElementById('fm1p1-blk1-d');

      var blk2Dot = document.getElementById('fm1p1-blk2-dot');
      var blk2T = document.getElementById('fm1p1-blk2-t');
      var blk2D = document.getElementById('fm1p1-blk2-d');
      var blk2D2 = document.getElementById('fm1p1-blk2-d2');

      var blk3Dot = document.getElementById('fm1p1-blk3-dot');
      var blk3T = document.getElementById('fm1p1-blk3-t');
      var blk3D = document.getElementById('fm1p1-blk3-d');

      var alertBg = document.getElementById('fm1p1-alert-bg');
      var alertTag = document.getElementById('fm1p1-alert-tag');
      var alertTxt1 = document.getElementById('fm1p1-alert-txt1');
      var alertTxt2 = document.getElementById('fm1p1-alert-txt2');
      var badgeEBg = document.getElementById('fm1p1-badge-e-bg');

      // Atualiza a Interface
      function updateUI() {
        // Estágios
        stageS.setAttribute('data-active', (state.mode === 'ste' && state.stage === 's') ? 'true' : 'false');
        stageT.setAttribute('data-active', (state.mode === 'ste' && state.stage === 't') ? 'true' : 'false');
        stageE.setAttribute('data-active', (state.mode === 'ste' && state.stage === 'e') ? 'true' : 'false');

        // Ativação da Semente no Estágio E
        if (state.mode === 'ste' && state.stage === 'e') {
          badgeEBg.setAttribute('fill', 'var(--fm1p1-teal, #14b8a6)');
        } else {
          badgeEBg.setAttribute('fill', 'var(--fm1p1-ink-muted, #64748b)');
        }

        // Abas
        tabSte.setAttribute('data-active', state.mode === 'ste' ? 'true' : 'false');
        tabErr.setAttribute('data-active', state.mode === 'err' ? 'true' : 'false');

        // Conteúdo do Painel
        var data = (state.mode === 'err') ? ERR_DATA : STE_DATA[state.stage];

        badgeBg.setAttribute('fill', data.badgeBg);
        badgeTxt.setAttribute('fill', data.badgeColor);
        badgeTxt.textContent = data.badge;

        mainTitle.textContent = data.title;
        mainDesc.textContent = data.desc;

        blk1T.textContent = data.b1_t;
        blk1D.textContent = data.b1_d;

        blk2T.textContent = data.b2_t;
        blk2D.textContent = data.b2_d;
        blk2D2.textContent = data.b2_d2 || '';

        blk3T.textContent = data.b3_t;
        blk3D.textContent = data.b3_d;

        // Estilização da caixa de alerta
        alertTag.textContent = data.alertTag;
        alertTxt1.textContent = data.alertT1;
        alertTxt2.textContent = data.alertT2;

        if (data.alertStyle === 'red') {
          alertBg.setAttribute('fill', 'var(--fm1p1-red-bg, rgba(244,63,94,0.15))');
          alertBg.setAttribute('stroke', 'var(--fm1p1-red, #f43f5e)');
          alertTag.setAttribute('fill', 'var(--fm1p1-red, #f43f5e)');
        } else if (data.alertStyle === 'amber') {
          alertBg.setAttribute('fill', 'var(--fm1p1-amber-bg, rgba(245,158,11,0.15))');
          alertBg.setAttribute('stroke', 'var(--fm1p1-amber, #f59e0b)');
          alertTag.setAttribute('fill', 'var(--fm1p1-amber, #f59e0b)');
        } else {
          alertBg.setAttribute('fill', 'var(--fm1p1-green-bg, rgba(16,185,129,0.15))');
          alertBg.setAttribute('stroke', 'var(--fm1p1-green, #10b981)');
          alertTag.setAttribute('fill', 'var(--fm1p1-green, #10b981)');
        }
      }

      // Listeners de Eventos
      function setStage(stg) {
        state.mode = 'ste';
        state.stage = stg;
        updateUI();
      }

      function setMode(md) {
        state.mode = md;
        updateUI();
      }

      stageS.addEventListener('click', function() { setStage('s'); });
      stageT.addEventListener('click', function() { setStage('t'); });
      stageE.addEventListener('click', function() { setStage('e'); });

      hsNeck.addEventListener('click', function() { setStage('s'); });

      tabSte.addEventListener('click', function() { setMode('ste'); });
      tabErr.addEventListener('click', function() { setMode('err'); });

      // Suporte a Teclado (Acessibilidade)
      var handleKey = function(evt, action) {
        if (evt.key === 'Enter' || evt.key === ' ') {
          evt.preventDefault();
          action();
        }
      };

      stageS.addEventListener('keydown', function(e) { handleKey(e, function() { setStage('s'); }); });
      stageT.addEventListener('keydown', function(e) { handleKey(e, function() { setStage('t'); }); });
      stageE.addEventListener('keydown', function(e) { handleKey(e, function() { setStage('e'); }); });
      hsNeck.addEventListener('keydown', function(e) { handleKey(e, function() { setStage('s'); }); });
      tabSte.addEventListener('keydown', function(e) { handleKey(e, function() { setMode('ste'); }); });
      tabErr.addEventListener('keydown', function(e) { handleKey(e, function() { setMode('err'); }); });

      // Inicialização
      updateUI();
    })();
  //
